SELECT (t.ts + {shift}) / {DAY_MS} AS d, ((t.ts + {shift}) / 3600000) % 24 AS h, COUNT(*), COALESCE(SUM(t.input_tokens),0), COALESCE(SUM(t.output_tokens),0), COALESCE(SUM(t.cache_read_tokens),0), COALESCE(SUM(t.cache_write_5m_tokens + t.cache_write_1h_tokens),0), COALESCE(SUM(t.cost_usd),0) FROM turn t JOIN session s ON s.kind=t.kind AND s.session_id=t.session_id WHERE {where_sql} GROUP BY d, h ORDER BY d, h